import { Component, inject } from '@angular/core';
import { DecimalPipe, NgTemplateOutlet } from '@angular/common';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { NzTableModule } from 'ng-zorro-antd/table';
import { HrmUserCell, HrmTagsCell, HrmAmountCell, HrmStatusCell, HrmTagItem, HrmStatusTone } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample } from '../../../doc/sg-blocks';

type EmpStatus = 'active' | 'leave' | 'absent';
interface Emp { name: string; pos: string; salary: number; status: EmpStatus; skills: HrmTagItem[]; }
interface Group { dept: string; rows: Emp[]; }

/** Doc page · Grouped Table (Table & List). Ví dụ dùng thành phần Table Cells (user/tags/amount/status). Song ngữ qua i18n docs.gridGrouped.*. */
@Component({
  selector: 'sg-doc-grouped',
  imports: [NgTemplateOutlet, DecimalPipe, TranslateModule, NzTableModule, HrmUserCell, HrmTagsCell, HrmAmountCell, HrmStatusCell, SgDoc, SgUse, SgDo, SgDont, SgExample],
  template: `
    <sg-doc category="Table & List" [title]="'docs.gridGrouped.title' | translate" [desc]="'docs.gridGrouped.desc' | translate"
      [related]="[{label:'User Cell', route:'hrm/table-cells/user'},{label:'Status Cell', route:'hrm/table-cells/status'},{label:'Amount Cell', route:'hrm/table-cells/amount'}]">

      <div sgOverview>
        <div style="width:100%"><ng-container [ngTemplateOutlet]="grid" /></div>
      </div>

      <div sgUsage>
        <sg-use [purpose]="'docs.gridGrouped.purpose' | translate" [when]="when"
          [behavior]="'docs.gridGrouped.behavior' | translate"
          [avoid]="'docs.gridGrouped.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do>{{ 'docs.gridGrouped.do1' | translate }}</sg-do>
        <sg-do>{{ 'docs.gridGrouped.do2' | translate }}</sg-do>
        <sg-dont>{{ 'docs.gridGrouped.dont1' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.gridGrouped.exT' | translate"
          [desc]="'docs.gridGrouped.exD' | translate">
          <div style="width:100%"><ng-container [ngTemplateOutlet]="grid" /></div>
        </sg-example>
      </div>

      <ng-template #grid>
        <nz-table [nzData]="groups" [nzShowPagination]="false" nzSize="small">
          <thead><tr><th>{{ 'docs.gridGrouped.colEmployee' | translate }}</th><th>{{ 'docs.gridGrouped.colSkills' | translate }}</th><th style="text-align:right">{{ 'docs.gridGrouped.colSalary' | translate }}</th><th>{{ 'docs.gridGrouped.colStatus' | translate }}</th></tr></thead>
          <tbody>
            @for (g of groups; track g.dept) {
              <tr class="grp">
                <td colspan="4"><b>{{ g.dept | translate }}</b> · {{ g.rows.length }} {{ 'docs.gridGrouped.people' | translate }} · {{ 'docs.gridGrouped.total' | translate }} {{ groupTotal(g) | number:'1.0-0' }} ₫</td>
              </tr>
              @for (r of g.rows; track r.name) {
                <tr>
                  <td><hrm-user-cell [name]="r.name" [sub]="r.pos | translate" [colorful]="true" [avatarSize]="34" /></td>
                  <td><hrm-tags-cell [tags]="skillsOf(r)" [max]="2" /></td>
                  <td style="text-align:right"><hrm-amount-cell [value]="r.salary" currency="₫" /></td>
                  <td><hrm-status-cell [status]="tone(r.status)" [label]="label(r.status)" variant="badge" [dot]="true" /></td>
                </tr>
              }
            }
          </tbody>
        </nz-table>
      </ng-template>

    </sg-doc>
  `,
  styles: [`:host ::ng-deep tr.grp td { background: var(--bg-surface-subtle); color: var(--text-strong); font-size: var(--fs-13); }`],
})
export class SgDocGrouped {
  private readonly t = inject(TranslateService);

  protected readonly groups: Group[] = [
    { dept: 'docs.gridGrouped.deptSales', rows: [
      { name: 'Nguyễn Minh Tuấn', pos: 'docs.gridGrouped.posManager', salary: 32000000, status: 'active', skills: [{ label: 'docs.gridGrouped.skillManagement', color: 'blue' }, { label: 'docs.gridGrouped.skillNegotiation', color: 'purple' }] },
      { name: 'Trần Thu Hà', pos: 'docs.gridGrouped.posStaff', salary: 18000000, status: 'leave', skills: [{ label: 'CRM', color: 'green' }, { label: 'Excel', color: 'teal' }] },
    ] },
    { dept: 'docs.gridGrouped.deptEng', rows: [
      { name: 'Lê Quốc Bảo', pos: 'docs.gridGrouped.posEngineer', salary: 25000000, status: 'active', skills: [{ label: 'Angular', color: 'blue' }, { label: 'Node', color: 'green' }] },
      { name: 'Đỗ Văn Nam', pos: 'docs.gridGrouped.posEngineer', salary: 24000000, status: 'active', skills: [{ label: 'Java', color: 'orange' }, { label: 'SQL', color: 'cyan' }] },
      { name: 'Võ Thành Trung', pos: 'docs.gridGrouped.posIntern', salary: 8000000, status: 'absent', skills: [{ label: 'Git', color: 'red' }] },
    ] },
    { dept: 'docs.gridGrouped.deptFinance', rows: [
      { name: 'Bùi Hải Yến', pos: 'docs.gridGrouped.posAccountant', salary: 20000000, status: 'active', skills: [{ label: 'docs.gridGrouped.skillAudit', color: 'purple' }, { label: 'Excel', color: 'teal' }] },
    ] },
  ];

  /** Nhãn kỹ năng: key domain → dịch qua translate; proper noun (Angular, Excel…) giữ literal. */
  protected skillsOf(r: Emp): HrmTagItem[] {
    return r.skills.map((s) => ({ ...s, label: this.t.instant(s.label) }));
  }

  protected groupTotal(g: Group): number { return g.rows.reduce((s, r) => s + r.salary, 0); }
  protected tone(s: EmpStatus): HrmStatusTone { return s === 'active' ? 'success' : s === 'leave' ? 'warning' : 'error'; }
  protected label(s: EmpStatus): string {
    return this.t.instant(s === 'active' ? 'docs.gridGrouped.statusActive' : s === 'leave' ? 'docs.gridGrouped.statusLeave' : 'docs.gridGrouped.statusAbsent');
  }

  protected readonly when = ['docs.gridGrouped.when1', 'docs.gridGrouped.when2'];
}
